INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at, created_at, updated_at)
    VALUES (
        '2112efe5-45f4-47a3-975b-c1b96e07212b',
        '21feff02-016d-46e2-bb9d-c27495133b1b',
        '63. óra: Csoportosítások',
        'Konkrét elemek adott szempontok szerinti csoportokba rendezése.',
        'Matematika',
        '5. osztály',
        'Geometria',
        '[{"id": "82a99517-0581-4216-8dae-d4a675662e31", "text": "Mit jelent a geometriai alakzatok csoportosítása?", "type": "multiple-choice", "options": [{"id": "a8b0130d-062e-45ff-bb5d-ee2ce55a0b0d", "text": "Alakzatok rendszerezése közös tulajdonságok (pl. oldalak száma, forma) alapján", "isCorrect": true}, {"id": "b3af94ab-a8d7-4776-957c-3d86dae0ad71", "text": "Alakzatok kiszínezése véletlenszerűen", "isCorrect": false}, {"id": "3f9dd4fa-cf11-4c47-a551-33e4cc44c5e7", "text": "Alakzatok megsemmisítése", "isCorrect": false}, {"id": "c79fef46-dc38-4b5b-b754-5ad33d459d0e", "text": "Alakzatok elforgatása 90 fokkal", "isCorrect": false}], "timeLimit": 15}, {"id": "84b8edc0-7436-4325-bd3a-94a0aa7b131f", "text": "Ha a testeket úgy csoportosítjuk, hogy vannak-e csúcsaik, a golyó a csúccsal rendelkező csoportba tartozik.", "type": "true-false", "options": [{"id": "57ee1ed0-35d6-4982-88c1-ff3149e71d21", "text": "Igaz", "isCorrect": false}, {"id": "430fab09-77cc-4a79-8e65-fe824a592b07", "text": "Hamis (a golyónak/gömbnek nincs csúcsa)", "isCorrect": true}], "timeLimit": 15}, {"id": "8d0ba93f-ed43-40cc-9135-5cb80fe6cfca", "text": "Melyik szempont szerint csoportosíthatjuk a síkidomokat?", "type": "multiple-choice", "options": [{"id": "550ce1c2-afe4-4649-92cf-fb096fd730d1", "text": "Oldalak száma (pl. háromszögek, négyszögek)", "isCorrect": true}, {"id": "f062e294-a6f9-4264-b830-8800ef8b8d23", "text": "Súlyuk szerint", "isCorrect": false}, {"id": "f9e9e05f-73cf-4a0f-b3ad-cbe663ee01ae", "text": "Hőmérsékletük szerint", "isCorrect": false}, {"id": "8a715690-4d83-44b6-b33a-2d20a652012c", "text": "Ízük szerint", "isCorrect": false}], "timeLimit": 15}, {"id": "1ccf53a0-375b-4fc8-9d74-6226d3e5b19f", "text": "Hány oldala van egy ötszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "afc15943-f124-4d0c-8d15-92268a55033b", "text": "Egy háromszög és egy négyszög egy csoportba tartozik, ha az oldalak száma a csoportosítási szempont.", "type": "true-false", "options": [{"id": "dfef842c-d0e9-4457-aacc-7452488bf2b2", "text": "Igaz", "isCorrect": false}, {"id": "d1c053a4-027f-4642-9b2f-43a2fd9ccd4d", "text": "Hamis (eltér az oldalaik száma)", "isCorrect": true}], "timeLimit": 15}, {"id": "069f500d-eca6-44f4-9ef9-e879a0d0fac9", "text": "Melyik alakzat NEM síkidom a következők közül?", "type": "multiple-choice", "options": [{"id": "85604f49-03e5-40e4-a532-3d437bbc7ac9", "text": "Kocka (mert az térbeli test)", "isCorrect": true}, {"id": "a13abf47-eed7-4d9c-bae7-40b76f3baca0", "text": "Négyzet", "isCorrect": false}, {"id": "252fc5d3-01fe-41a6-86f6-b85ad0f4ca86", "text": "Kör", "isCorrect": false}, {"id": "c7781fda-dca7-420e-8957-89d813853205", "text": "Háromszög", "isCorrect": false}], "timeLimit": 15}, {"id": "3b405767-dd39-4a17-87d1-b7372f29a315", "text": "A négyzet és a téglalap egyaránt 4 csúccsal rendelkező négyszög.", "type": "true-false", "options": [{"id": "00a2ec76-ca5f-4770-89c6-c208bcdd4d25", "text": "Igaz", "isCorrect": true}, {"id": "91ab98b1-2e7a-410f-962f-c0f936e4ddd3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb,
        true,
        NOW(),
        NOW(),
        NOW()
    );

INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at, created_at, updated_at)
    VALUES (
        '52e4a968-3453-47c3-914d-d210657cbb00',
        '21feff02-016d-46e2-bb9d-c27495133b1b',
        '64. óra: Halmazok',
        'Halmaz, halmazábra, halmazok egyesítése és közös része.',
        'Matematika',
        '5. osztály',
        'Geometria',
        '[{"id": "1bab920a-bc11-4193-b5f9-1f05ccdbb5c5", "text": "Mit nevezünk két halmaz közös részének (metszetének)?", "type": "multiple-choice", "options": [{"id": "efae8cd3-5bca-4d43-b535-fae1f9e94a24", "text": "Azokat az elemeket, amelyek mindkét halmazban benne vannak", "isCorrect": true}, {"id": "0c7e4cb3-f766-4b1d-a560-2b7ace265931", "text": "Azokat az elemeket, amelyek egyik halmazban sincsenek benne", "isCorrect": false}, {"id": "333b4b7f-53a1-4356-9367-b32a9606b9e4", "text": "Csak az első halmaz elemeit", "isCorrect": false}, {"id": "13ddf187-b5b8-47f4-a98f-20f03bd384e4", "text": "A két halmaz elemeinek összegét", "isCorrect": false}], "timeLimit": 15}, {"id": "ba25aa9f-1409-4ead-ae4a-1a7e122d06fd", "text": "A Venn-diagram (halmazábra) segítségével ábrázolhatók a halmazok és kapcsolataik.", "type": "true-false", "options": [{"id": "3027119c-2ef3-4abd-b25e-baf1440e0de8", "text": "Igaz", "isCorrect": true}, {"id": "c19c3595-d494-4be6-a0a9-e19982a8255a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6ea51fba-61ec-457a-bbb3-114261167ad1", "text": "Ha az A halmazban piros alakzatok vannak, a B halmazban háromszögek, mi kerül a közös részbe?", "type": "multiple-choice", "options": [{"id": "f097e3b9-7d52-4db3-920a-8ea76297805c", "text": "A piros háromszögek", "isCorrect": true}, {"id": "9d5d95bb-d59c-4191-ac89-0c2943c77311", "text": "A kék négyzetek", "isCorrect": false}, {"id": "503b3af2-c29e-48cb-9c54-cd8477d1716c", "text": "Minden piros alakzat", "isCorrect": false}, {"id": "0699ba6b-51a1-48de-97ef-533b9f7cd34b", "text": "Minden háromszög", "isCorrect": false}], "timeLimit": 15}, {"id": "8c9b60cb-9ba5-44bd-8097-231dee384aa9", "text": "Mit jelent két halmaz egyesítése (uniója)?", "type": "multiple-choice", "options": [{"id": "f7bd6d79-bb96-4a8a-8999-468217d22b36", "text": "Azokat az elemeket, amelyek legalább az egyik halmazhoz tartoznak", "isCorrect": true}, {"id": "64919bc8-82d6-4edc-a721-c6456b784d00", "text": "Csak a közös elemeket", "isCorrect": false}, {"id": "7a5f50f7-8843-405f-a703-190fd3a77aa2", "text": "Az üres halmazt", "isCorrect": false}, {"id": "f566e5f0-7171-40e7-b836-8d3bcf816f04", "text": "Az elemek kivonását", "isCorrect": false}], "timeLimit": 15}, {"id": "12e81c99-2855-40b5-a6c6-c038f5b28ac8", "text": "Ha az A halmazban a 2-vel osztható számok, a B-ben a 3-mal osztható számok vannak, a 6 a közös részben van.", "type": "true-false", "options": [{"id": "71217506-ea41-4427-8b0d-e7bd9654f91d", "text": "Igaz (mert 6 osztható 2-vel és 3-mal is)", "isCorrect": true}, {"id": "a21b855d-903b-4747-952c-f3df6d6714da", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7f2f05e0-3f4a-4d4e-9de6-8dbd6715192d", "text": "Hogy hívjuk azt a halmazt, amelynek egyetlen eleme sincs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "üres halmaz"}, {"id": "21553e4b-505b-4e0d-9ba8-120cf951a038", "text": "A halmaz elemei sorrendje számít a halmaz megadásakor.", "type": "true-false", "options": [{"id": "1c6a6d0d-9700-4e14-866a-e697a80a8b83", "text": "Igaz", "isCorrect": false}, {"id": "aad45dd4-0ff6-4ff6-8130-f6ff78addb16", "text": "Hamis (a halmaz elemeinek sorrendje közömbös)", "isCorrect": true}], "timeLimit": 15}]'::jsonb,
        true,
        NOW(),
        NOW(),
        NOW()
    );

INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at, created_at, updated_at)
    VALUES (
        '05744a24-0929-4123-8ce0-4238c5e68c85',
        '21feff02-016d-46e2-bb9d-c27495133b1b',
        '65. óra: Halmazok (Részhalmaz, komplementer halmaz)',
        'Részhalmaz, komplementer halmaz elemeinek megadása és ábrázolása.',
        'Matematika',
        '5. osztály',
        'Geometria',
        '[{"id": "eb2114ca-5da9-4745-8b8d-d8f16a0fc349", "text": "Mikor mondjuk, hogy az A halmaz részhalmaza a B halmaznak?", "type": "multiple-choice", "options": [{"id": "df53c4ac-f9f1-41e5-9744-a4d6b7afa4d3", "text": "Ha az A halmaz minden eleme benne van a B halmazban is", "isCorrect": true}, {"id": "37dcb204-f41b-456d-a97f-085a54471c2b", "text": "Ha az A halmaz több elemet tartalmaz, mint B", "isCorrect": false}, {"id": "2258f6c8-333a-4e1f-8498-6c43d5da598b", "text": "Ha nincs közös elemük", "isCorrect": false}, {"id": "f04430cc-1242-4813-83b8-8353c30c5012", "text": "Ha B üres halmaz", "isCorrect": false}], "timeLimit": 15}, {"id": "c3ee3ad2-3be8-441a-99a0-4ab7c44a1a92", "text": "A négyzetek halmaza részhalmaza a téglalapok halmazának.", "type": "true-false", "options": [{"id": "9d90986d-10a3-40d8-ac8b-0885d73eb96f", "text": "Igaz (minden négyzet egyben téglalap is)", "isCorrect": true}, {"id": "f43c0cbf-34d8-451a-ac02-055c4fd7d203", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "797586af-4811-4426-bba3-64ed99e13fd6", "text": "Mit jelent egy A halmaz komplementere (kiegészítő halmaza) az alaphalmazhoz képest?", "type": "multiple-choice", "options": [{"id": "ae53471a-b517-4790-b433-8268f1e25337", "text": "Azokat az elemeket az alaphalmazból, amelyek NEM tartoznak az A halmazhoz", "isCorrect": true}, {"id": "da7444a3-9bc8-4d87-88d5-2a320c2be58b", "text": "Az A halmaz elemeinek dupláját", "isCorrect": false}, {"id": "53eb22fb-73f0-4e6a-8a9a-5e117583d1f1", "text": "Csak az A halmaz elemeit", "isCorrect": false}, {"id": "b89152f6-359c-4888-9850-1b484e0b0067", "text": "Az üres halmazt", "isCorrect": false}], "timeLimit": 15}, {"id": "f4a6ef95-922e-4d44-81c4-b4eff77aec22", "text": "Ha az alaphalmaz az 5. osztályos tanulók, és az A halmaz a fiúk, ki alkotja az A komplementerét?", "type": "multiple-choice", "options": [{"id": "270d4779-8b74-4ac5-b960-a52e2512012d", "text": "Az 5. osztályos lányok", "isCorrect": true}, {"id": "6f609cff-fe88-4c0c-bbac-46c9db0696d3", "text": "Minden 5. osztályos fiú", "isCorrect": false}, {"id": "bcffdfc7-b12c-4ae5-ab1a-06ee4094938c", "text": "A tanárok", "isCorrect": false}, {"id": "002759d9-3006-4929-95d5-7e75fdd452d1", "text": "A 6. osztályosok", "isCorrect": false}], "timeLimit": 15}, {"id": "a6284cfb-0893-4dd4-b7bd-bf77177e897a", "text": "Az üres halmaz minden halmaznak részhalmaza.", "type": "true-false", "options": [{"id": "5b1793cf-2f8e-4e2e-a0a6-da8cf5588549", "text": "Igaz", "isCorrect": true}, {"id": "5d5d8a8a-8251-4139-bdf4-e8721f91bc1f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cbd4788a-706e-409e-b8d0-7d0c8010b96d", "text": "Hány elemű az {1, 3, 5, 7} halmaz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "8f42d01e-00c2-4be2-aaa1-e5f8029d35f7", "text": "Minden téglalap egyben négyzet is.", "type": "true-false", "options": [{"id": "af3aec76-7f2f-442b-9fe5-05d8847bf570", "text": "Igaz", "isCorrect": false}, {"id": "1b4197ca-2a4d-4d6d-8a09-39e3b0f506e1", "text": "Hamis (csak az a téglalap négyzet, amelynek minden oldala egyenlő)", "isCorrect": true}], "timeLimit": 15}]'::jsonb,
        true,
        NOW(),
        NOW(),
        NOW()
    );

INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at, created_at, updated_at)
    VALUES (
        '486fd930-bb01-4477-a057-ebeea59d4bda',
        '21feff02-016d-46e2-bb9d-c27495133b1b',
        '66. óra: Test, felület, vonal, pont',
        'Test, felület, vonal, pont. Egyenes, félegyenes, szakasz, sík.',
        'Matematika',
        '5. osztály',
        'Geometria',
        '[{"id": "2596e6a2-5f66-4a4b-9f1a-73634b09a189", "text": "Melyik geometriai alapfogalomnak nincs kiterjedése (hossza, szélessége, magassága)?", "type": "multiple-choice", "options": [{"id": "eaaa7ead-986e-4def-8269-973b2845e410", "text": "Pont", "isCorrect": true}, {"id": "ca0ef959-53af-4473-927e-c9505c452b48", "text": "Egyenes", "isCorrect": false}, {"id": "9bff53ae-39a5-48a6-9e15-a548d5853bf6", "text": "Sík", "isCorrect": false}, {"id": "cf1ae250-95e7-481a-87df-305751c4e017", "text": "Test", "isCorrect": false}], "timeLimit": 15}, {"id": "4126935c-5450-4d48-be0c-ad6857c81478", "text": "Miben különbözik a szakasz az egyenestől?", "type": "multiple-choice", "options": [{"id": "a128f55f-eddb-499f-b430-c3891e81cc7e", "text": "A szakasz mindkét irányban korlátos (két végpontja van)", "isCorrect": true}, {"id": "29aca0a6-0956-4cbc-a7da-3cb88ca584f1", "text": "A szakasz végtelen hosszú", "isCorrect": false}, {"id": "30cf5a88-15d9-431a-b472-ab35e30cf35d", "text": "A szakasz görbe vonal", "isCorrect": false}, {"id": "a499f19f-0d6b-462f-b1c5-85536b03bbf4", "text": "Nincs különbség köztük", "isCorrect": false}], "timeLimit": 15}, {"id": "a67183b6-ea7b-421f-b045-2a945f7bd6bd", "text": "A félegyenesnek van kezdőpontja, de másik irányban végtelenbe nyúlik.", "type": "true-false", "options": [{"id": "9c9f302e-2055-43c6-ad68-88e19277e434", "text": "Igaz", "isCorrect": true}, {"id": "58337b55-4ee2-4889-802e-3ef6bb90f060", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "aab851a0-38ec-491c-80e3-ea71c60c67cd", "text": "Mivel mérjük két pont távolságát a síkban?", "type": "multiple-choice", "options": [{"id": "fc67fde5-b933-4b67-bae1-dfcffb36543d", "text": "A két pontot összekötő szakasz hosszával", "isCorrect": true}, {"id": "3d927218-0930-4071-a3e7-222db0c081a7", "text": "A két pont közötti terület nagyságával", "isCorrect": false}, {"id": "37e6d072-72bf-4fad-8f96-3686753d8b38", "text": "Szögmérővel fokokban", "isCorrect": false}, {"id": "36cbf6c7-6641-4e1e-bae9-631fdbde8a34", "text": "Literekben", "isCorrect": false}], "timeLimit": 15}, {"id": "a5a37c49-fe3a-4b1b-bf0e-3d084c8aca9f", "text": "Hány végpontja van egy szakasznak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "27d621b1-df0b-4b8d-b3b2-372608fbad6f", "text": "Egy téglalap felülete kétdimenziós (síkbeli), míg a kocka egy háromdimenziós test.", "type": "true-false", "options": [{"id": "c7832929-a097-427c-ac47-1acd2d5d03b6", "text": "Igaz", "isCorrect": true}, {"id": "1bbbd7be-77f6-4363-a66e-d9e74725ac87", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e2430d1f-8322-40a0-b9f1-0fcad8fd2339", "text": "Hány egyenes fektethető át két különböző ponton?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}]'::jsonb,
        true,
        NOW(),
        NOW(),
        NOW()
    );

INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at, created_at, updated_at)
    VALUES (
        'd9e5bd17-2793-48b3-8a75-a77705c1a32e',
        '21feff02-016d-46e2-bb9d-c27495133b1b',
        '67. óra: A szög',
        'Szögtartomány, szög csúcsa, szög szárai, szögfajták, szögmérő használata.',
        'Matematika',
        '5. osztály',
        'Geometria',
        '[{"id": "65495720-c7ad-4c9b-9548-bcba6c3a67d6", "text": "Hogy nevezzük azt a szöget, amely pontosan 90 fokos?", "type": "multiple-choice", "options": [{"id": "a1d55d42-4e6e-4658-b345-be605cc1d4b4", "text": "Derékszög", "isCorrect": true}, {"id": "c7af38e0-df61-4d03-9118-9d33b7273c20", "text": "Hegyesszög", "isCorrect": false}, {"id": "e902c733-d50f-4bc0-8e29-4d784aaafded", "text": "Tompaszög", "isCorrect": false}, {"id": "01960889-ce2f-4b95-b22e-7fed2410f8e7", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "bf1c6a28-5975-4918-89d5-6275e7cd60c7", "text": "Milyen szög az, amely 0 foknál nagyobb, de 90 foknál kisebb?", "type": "multiple-choice", "options": [{"id": "08f1b244-438a-442f-8762-b230f8234271", "text": "Hegyesszög", "isCorrect": true}, {"id": "312df052-711b-4122-b62d-0739ea368bc4", "text": "Tompaszög", "isCorrect": false}, {"id": "4c16b732-32e2-47d3-a99f-19a7c3964255", "text": "Derékszög", "isCorrect": false}, {"id": "1d34a6ce-5701-4c32-bbe2-858edf592eae", "text": "Homorúszög", "isCorrect": false}], "timeLimit": 15}, {"id": "bb99934b-f3ec-4b16-80b6-43b510edc2d2", "text": "Hány fokos az egyenesszög?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "75c62f95-6121-453a-9e72-adf73372aed3", "text": "A 120 fokos szög tompaszög.", "type": "true-false", "options": [{"id": "3178cc89-7733-45a4-bf6f-251f08d5f601", "text": "Igaz (mert 90 foknál nagyobb és 180 foknál kisebb)", "isCorrect": true}, {"id": "99aab467-8a3e-4830-bc66-89d2814c8a6e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "702fe25e-8728-4540-818f-948bd7490eac", "text": "Mi a szög mértékegysége?", "type": "multiple-choice", "options": [{"id": "38bfccc3-5f81-4e62-a8ce-9fee1f349f86", "text": "Fok (°)", "isCorrect": true}, {"id": "89f38f09-39fa-4ece-b658-367bc163f0a4", "text": "Centiméter (cm)", "isCorrect": false}, {"id": "0cedb3d1-047f-4999-9305-e9a8e0e15d08", "text": "Gramm (g)", "isCorrect": false}, {"id": "ad2160b7-bbe1-46da-bfb8-197275f0b1a1", "text": "Liter (l)", "isCorrect": false}], "timeLimit": 15}, {"id": "b8b1d767-4682-4075-bd99-41c96d97194c", "text": "Hány fok a teljesszög?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "371e054a-af41-4daf-933c-be543a70cc28", "text": "A szög szárai két félegyenes, amelyek közös kezdőpontja a szög csúcsa.", "type": "true-false", "options": [{"id": "2f031b01-a5d6-4a7a-84e9-0a968961a123", "text": "Igaz", "isCorrect": true}, {"id": "b962a02a-6c51-4218-9a44-7fb97f9209fb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb,
        true,
        NOW(),
