        'Matematika',
        '5. osztály',
        'Geometria',
        '[{"id": "0c926814-488e-4a43-84a8-c81bda948f6e", "text": "Mit nevezünk sokszög átlójának?", "type": "multiple-choice", "options": [{"id": "f82d2df6-bcdd-463b-a8c2-821b6fcb1926", "text": "Két nem szomszédos csúcsot összekötő szakaszt", "isCorrect": true}, {"id": "c152bd32-1b24-4e38-8daf-56e53b93fc23", "text": "A sokszög oldalát", "isCorrect": false}, {"id": "33d21ced-7e14-4e7a-948f-b699bd633744", "text": "A sokszög kerületét", "isCorrect": false}, {"id": "6c28da6e-5a4d-4a4c-8595-2413076d4528", "text": "A sokszög középpontját", "isCorrect": false}], "timeLimit": 15}, {"id": "5c9fff90-91b5-44ce-bfaf-434e24021184", "text": "Hány átlója van egy háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0"}, {"id": "d4c66d43-6873-4558-944f-04cea9df222e", "text": "A háromszögeknek nincsenek átlói, mert minden csúcsuk szomszédos egymással.", "type": "true-false", "options": [{"id": "ec11317a-8f6d-4381-9eca-50b0045dad2f", "text": "Igaz", "isCorrect": true}, {"id": "d143f712-882c-41f5-b356-e6b4149dc08a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e35c18a1-6fbf-44ff-bb4b-4e6ff56aef60", "text": "Hány csúcsa és oldala van egy négyszögnek?", "type": "multiple-choice", "options": [{"id": "a0c6c8b0-c122-47f9-bc23-2a8f56530765", "text": "4 csúcsa és 4 oldala", "isCorrect": true}, {"id": "308a73db-462f-465b-824e-757604f98515", "text": "3 csúcsa és 4 oldala", "isCorrect": false}, {"id": "f73ca853-82ea-4c28-8ff2-66dab8d5513e", "text": "4 csúcsa és 2 átlója (de 6 oldala)", "isCorrect": false}, {"id": "d4090d49-3927-4288-8fce-0311a6095c0b", "text": "5 csúcsa és 5 oldala", "isCorrect": false}], "timeLimit": 15}, {"id": "34e31fbc-9282-4cb3-9300-8345a05220e7", "text": "Hány átlója van egy négyszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "47883271-157e-4f1c-bdd0-933fd6c176ea", "text": "Hogy nevezzük azt a sokszöget, amelynek 6 oldala van?", "type": "multiple-choice", "options": [{"id": "691e7d0b-5b36-467c-a714-90baa2c40d16", "text": "Hatszög", "isCorrect": true}, {"id": "87266a75-df71-46e6-8ca7-42575bacf565", "text": "Hétszög", "isCorrect": false}, {"id": "ccf52fae-75cd-4864-9d71-786eb08ae5a4", "text": "Ötszög", "isCorrect": false}, {"id": "5b51c23c-7922-4214-94fe-2ef4b8add20d", "text": "Négyszög", "isCorrect": false}], "timeLimit": 15}, {"id": "54c4adbe-bff2-43e1-a26a-f892c0326a01", "text": "A szabályos sokszög minden oldala és minden belső szöge egyenlő.", "type": "true-false", "options": [{"id": "e6b2a604-7a16-4c9b-b3fb-300f3032860b", "text": "Igaz", "isCorrect": true}, {"id": "52377bd0-c000-4da7-a980-de7cc833d339", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb,
