        'Matematika',
        '5. osztály',
        'Geometria',
        '[{"id": "0fc69407-6acb-4694-a759-65c04ede177e", "text": "Hány lapja van egy kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "a0b5b425-3089-46fd-afcc-0e3cca0bf03e", "text": "Hány csúcsa van egy kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "1d4ea002-7c86-4d90-a7a1-208007a6f12a", "text": "Hány éle van egy kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "94942753-e313-49d7-ada3-084a116a3b07", "text": "A téglatest minden lapja téglalap (amelyek közül egyesek lehetnek négyzetek is).", "type": "true-false", "options": [{"id": "3f3a255d-ba6b-4f76-b187-7accc9c4167b", "text": "Igaz", "isCorrect": true}, {"id": "8249d4b6-c332-414c-a713-7d44b5edc118", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "08293844-5c6f-402d-8ffc-ab7068dec7e8", "text": "Hogy nevezzük a test lapjainak találkozási vonalát?", "type": "multiple-choice", "options": [{"id": "c391f6ef-26de-4fbc-8695-a55ef94979fb", "text": "Él", "isCorrect": true}, {"id": "51e30262-b972-4f30-bb9e-0e79ff5ba90b", "text": "Csúcs", "isCorrect": false}, {"id": "174fa573-39a5-49df-b0a6-d07d85e61678", "text": "Átló", "isCorrect": false}, {"id": "50b21524-49f5-4291-99a8-687502eecb9a", "text": "Magasság", "isCorrect": false}], "timeLimit": 15}, {"id": "a3c18078-7e97-49d7-a1bc-2342ad2ae0e2", "text": "A gömbnek nincs sík lapja és nincs éle sem.", "type": "true-false", "options": [{"id": "57984748-4cc0-4f48-9715-281c08a9879c", "text": "Igaz", "isCorrect": true}, {"id": "a22d9745-5553-48eb-94b7-56637d48f1cd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f519ed77-caad-4f9d-8c93-52ae51814e04", "text": "Milyen síkidomok határolják a téglatestet?", "type": "multiple-choice", "options": [{"id": "2dc5ccd1-13ee-471e-92d8-229cc2229f8a", "text": "Téglalapok", "isCorrect": true}, {"id": "af38f2a4-8418-4847-90f6-68fe72686506", "text": "Háromszögek", "isCorrect": false}, {"id": "7362b625-4f68-46bc-9391-2523654d0930", "text": "Körök", "isCorrect": false}, {"id": "63f41cd2-7ae3-4d25-ba02-582f2a5bfbd5", "text": "Ötszögek", "isCorrect": false}], "timeLimit": 15}]'::jsonb,
        true,
        NOW(),
        NOW(),
        NOW()
    );

INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at, created_at, updated_at)
    VALUES (
        '6f0d22c9-478f-48fa-9b97-0bfd70427241',
        '21feff02-016d-46e2-bb9d-c27495133b1b',
