        'Látható és nem látható élek ábrázolása síkban, térbeli rajzolás.',
        'Matematika',
        '5. osztály',
        'Geometria',
        '[{"id": "5940f5d7-f9ab-4435-8558-e9e2630ec340", "text": "Hogyan jelöljük a térbeli ábrákon a nem látható (takarásban lévő) éleket?", "type": "multiple-choice", "options": [{"id": "6672161d-4b97-487a-943b-b7d994271b49", "text": "Szaggatott vagy pontozott vonallal", "isCorrect": true}, {"id": "d65b353a-ce69-487f-826d-c911b1108df6", "text": "Vastag folytonos vonallal", "isCorrect": false}, {"id": "a756f4b0-417d-4286-8bea-541b76c2f697", "text": "Piros hullámvonallal", "isCorrect": false}, {"id": "4ed204c0-2768-4f60-9ce3-c0b07923b7d1", "text": "Egyáltalán nem rajzoljuk le", "isCorrect": false}], "timeLimit": 15}, {"id": "e50e6892-771c-428a-8eb9-4731e071e2a5", "text": "A látható éleket folytonos vonallal rajzoljuk a tengelyes és térbeli ábrákon.", "type": "true-false", "options": [{"id": "1ff649d0-330f-449f-bc1c-2af0ea3be0f3", "text": "Igaz", "isCorrect": true}, {"id": "6abb90e3-7648-4a83-a344-5a67169e2f9e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8a786310-bc18-48af-9f58-b38558d207d6", "text": "Ha egy kockát elölről nézünk úgy, hogy csak az elülső lapját látjuk, hány éle van takarásban?", "type": "multiple-choice", "options": [{"id": "5d6cebd1-0241-4d86-b67a-1af001532ddb", "text": "8 éle (a hátsó lap 4 éle és a 4 összekötő él)", "isCorrect": true}, {"id": "9a62e2c1-d13f-4fe2-add6-be88f42250cd", "text": "0 éle", "isCorrect": false}, {"id": "3bb8a6ff-4a03-4f3a-8ad1-88442994e869", "text": "2 éle", "isCorrect": false}, {"id": "05d18e12-9ae8-4a35-9867-ea1976ebf104", "text": "12 éle", "isCorrect": false}], "timeLimit": 15}, {"id": "9f206831-9deb-4a10-841d-7ef8d71965da", "text": "Kocka hálója hány négyzetből áll?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "ad352c76-ddca-4bf7-b42b-ff184980b34e", "text": "A testek síkbeli rajzolásakor a 3 dimenziót jelenítjük meg a kétdimenziós lapon.", "type": "true-false", "options": [{"id": "a0a853de-d970-4547-891f-4a6b46abe4db", "text": "Igaz", "isCorrect": true}, {"id": "9feb960e-640d-44a4-baf5-527dc839c22b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c59228d0-ae41-4abd-9f86-eac0e9f96264", "text": "Hány lapja van egy négyzet alapú gúlának (piramisnak)?", "type": "multiple-choice", "options": [{"id": "da3713a8-e0a3-4bc0-ac65-7997aa177ee2", "text": "5 lapja (1 négyzet alap lap + 4 háromszög oldallap)", "isCorrect": true}, {"id": "549a3d21-63b0-4a76-a915-6f04354281b3", "text": "4 lapja", "isCorrect": false}, {"id": "e61aab3a-5037-4fc2-b861-8856ebb03da2", "text": "6 lapja", "isCorrect": false}, {"id": "9f7b25ba-bcf6-4e99-9c5e-7bdf46972530", "text": "8 lapja", "isCorrect": false}], "timeLimit": 15}, {"id": "1f14d8f7-1522-44b3-8a4d-09c6db554f5b", "text": "Egy hengert két egybevágó körlap és egy palást határol.", "type": "true-false", "options": [{"id": "e18dc720-6d47-4294-8bba-164aca34a06f", "text": "Igaz", "isCorrect": true}, {"id": "002dcb06-a674-4081-bb2d-755f14fc9a1f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb,
        true,
        NOW(),
        NOW(),
        NOW()
    );

INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at, created_at, updated_at)
    VALUES (
        '51c3b27b-0c6b-4e29-9019-bb2b504ada9b',
        '21feff02-016d-46e2-bb9d-c27495133b1b',
        '71. óra: Egyenesek síkban, térben',
        'Párhuzamos, merőleges és kitérő egyenesek. Pont és egyenes távolsága.',
        'Matematika',
        '5. osztály',
        'Geometria',
        '[{"id": "eeb02e36-df6f-4494-a4b8-f2a23f931135", "text": "Mikor mondjuk két síkbeli egyenesre, hogy párhuzamosak?", "type": "multiple-choice", "options": [{"id": "50fc8ed9-6d6f-4831-8449-cb1273edefcb", "text": "Ha nincs közös pontjuk (vagy egybeesnek)", "isCorrect": true}, {"id": "9a7be2f4-34f0-425e-ae53-662bb49e654f", "text": "Ha 90 fokos szöget zárnak be egymással", "isCorrect": false}, {"id": "7d6a6566-3e28-4e8d-bf85-91818ee2ab33", "text": "Ha egyetlen pontban metszik egymást", "isCorrect": false}, {"id": "e54647d6-6c3a-4f53-8776-373849c05cbf", "text": "Ha merőlegesek egymásra", "isCorrect": false}], "timeLimit": 15}, {"id": "0905f978-da16-4838-a319-eaac86f8b3d3", "text": "Milyen szöget zár be egymással két merőleges egyenes?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "d02049b9-6607-4f5e-af68-196b50fb7307", "text": "Mit nevezünk kitérő egyeneseknek a térben?", "type": "multiple-choice", "options": [{"id": "df54aa35-0950-4014-ab3a-10cc89878cc4", "text": "Olyan térbeli egyeneseket, amelyek nem egy síkban vannak és nem metszik egymást", "isCorrect": true}, {"id": "5e43979b-497f-4170-9862-56f0b2baef7a", "text": "Síkbeli merőleges egyeneseket", "isCorrect": false}, {"id": "c7b6f08e-ed10-4daa-93ea-c94f87551000", "text": "Egybeeső egyeneseket", "isCorrect": false}, {"id": "b0993894-8783-485c-8649-9d6a6236d80f", "text": "Párhuzamos síkbeli egyeneseket", "isCorrect": false}], "timeLimit": 15}, {"id": "0cb0ed43-2196-482c-acf1-01d8a6e6e8ad", "text": "Hogyan mérjük egy pont és egy egyenes távolságát?", "type": "multiple-choice", "options": [{"id": "8e67c09c-b296-46de-8308-18deaf84b9b2", "text": "A pontból az egyenesre bocsátott merőleges szakasz hosszával", "isCorrect": true}, {"id": "e2e30622-7318-4d63-a92b-243c8166e0f4", "text": "A pontból húzott tetszőleges ferde szakasz hosszával", "isCorrect": false}, {"id": "105737d3-cd69-43a5-9a52-9b7332e488dc", "text": "A pont és az egyenes tetszőleges pontjának távolságának átlagával", "isCorrect": false}, {"id": "08fad7b5-3e5b-4883-b53d-19258b65219a", "text": "Nem mérhető meg", "isCorrect": false}], "timeLimit": 15}, {"id": "8d24ad19-2e2c-462b-a4bb-3dd77c478aca", "text": "Két párhuzamos egyenes távolsága minden pontban ugyanannyi.", "type": "true-false", "options": [{"id": "7b58730f-40d9-483e-86ae-dc4068b35ba9", "text": "Igaz", "isCorrect": true}, {"id": "7ae88a91-d153-47c7-a3bf-dc305b54bf5d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c8f0a701-a4a1-4855-84ec-eb4dde8f885f", "text": "A füzet vonalazása egymással párhuzamos egyeneseket szemléltet.", "type": "true-false", "options": [{"id": "e171d854-4fc0-4fd8-9688-e5b3bbdbcc07", "text": "Igaz", "isCorrect": true}, {"id": "5858c88c-9e2b-42cc-9c07-72d2d82c6cfa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "05b8b928-fed3-44ba-9b9f-df444704af27", "text": "Hány merőleges egyenes húzható egy megadott ponton keresztül egy egyenesre a síkban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}]'::jsonb,
        true,
        NOW(),
        NOW(),
        NOW()
    );

