        '[{"id": "ce8caac2-1a80-4a01-be24-bf2eb2284cc9", "text": "Melyik állítás igaz a téglalapra?", "type": "multiple-choice", "options": [{"id": "90b76d5c-4f08-43b3-9945-59d7ff119ed7", "text": "Minden belső szöge derékszög (90°)", "isCorrect": true}, {"id": "01edbb67-c9e8-459c-b1a4-866e6f164758", "text": "Minden oldala kötelezően egyenlő hosszúságú", "isCorrect": false}, {"id": "95778d4c-0038-4294-b084-a47fbe17ece0", "text": "Átlói merőlegesek egymásra", "isCorrect": false}, {"id": "ec2f16e1-0862-48dc-872f-327a72aa192b", "text": "Csak 3 csúcsa van", "isCorrect": false}], "timeLimit": 15}, {"id": "d0433934-69bb-4e37-b5a0-7dd7f10c854b", "text": "Mi a különbség a négyzet és az általános téglalap között?", "type": "multiple-choice", "options": [{"id": "3fe51c0a-b367-43ee-9482-d7823ebd5121", "text": "A négyzet minden oldala egyenlő hosszúságú", "isCorrect": true}, {"id": "b57a4a31-919b-4782-8026-b246947d77ba", "text": "A négyzetnek nincsenek derékszögei", "isCorrect": false}, {"id": "c2e45c9d-98e6-4a37-8330-cc1036ed9487", "text": "A téglalapnak több csúcsa van", "isCorrect": false}, {"id": "85d2b91a-d374-44b0-adad-21055cc13a51", "text": "A négyzet nem síkidom", "isCorrect": false}], "timeLimit": 15}, {"id": "b1fa0763-09dd-4f4f-8824-bab048fb8049", "text": "A négyzet átlói egyenlő hosszúságúak és merőlegesen felezik egymást.", "type": "true-false", "options": [{"id": "bf639edc-36b8-4ec7-99db-f639dda609e2", "text": "Igaz", "isCorrect": true}, {"id": "b868c780-cdf6-4d35-8baf-e9df6a08cc8b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "38c7ca17-027c-4517-a599-09a391bc27ce", "text": "Mennyi egy 5 cm oldalú négyzet kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "296748a4-3c9c-4b97-b270-5406f737cd8b", "text": "Mennyi egy 4 cm és 6 cm oldalú téglalap kerülete? (2*(a+b))", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "fdc8e6b1-799b-448d-b35f-6a9806e36410", "text": "Mennyi a téglalap belső szögeinek összege?", "type": "multiple-choice", "options": [{"id": "7cd3f9d8-78ec-49ac-8435-ffe409c9cd00", "text": "360° (4 * 90°)", "isCorrect": true}, {"id": "3be7e5e6-d823-4913-8fb9-de0a9aebdea2", "text": "180°", "isCorrect": false}, {"id": "688bf60c-c0e2-4610-9002-936e92804af2", "text": "270°", "isCorrect": false}, {"id": "c04e80d0-9615-4ed8-ae79-dec7e9748ee3", "text": "90°", "isCorrect": false}], "timeLimit": 15}, {"id": "d543b16e-f25f-4335-af69-3eafb4a63870", "text": "A téglalap szemközti oldalai párhuzamosak és egyenlő hosszúságúak.", "type": "true-false", "options": [{"id": "9e213488-fb8e-412f-8b3c-f6c5214a7382", "text": "Igaz", "isCorrect": true}, {"id": "2b9a75b5-649e-42ef-80f3-8438a71ac32c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb,
        true,
        NOW(),
        NOW(),
        NOW()
    );

