281660276", "text": "Igaz", "isCorrect": true}, {"id": "d0a9fe52-f2cc-4a0b-abc4-fc8cfc6fa302", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2bcf7630-fba7-41c1-ac43-36941e5c8593", "text": "Melyik alakzatnak van 0 átlója?", "type": "multiple-choice", "options": [{"id": "67642bf3-48c8-4589-ac38-82b9f13fdd22", "text": "Háromszög", "isCorrect": true}, {"id": "7c141307-9c37-4e07-9802-f9d5f08857ff", "text": "Négyzet", "isCorrect": false}, {"id": "20054ffc-54ba-424a-bbeb-b6eaf3dbd357", "text": "Téglalap", "isCorrect": false}, {"id": "f96c0920-a26c-4c2e-a69f-bdeedebbda63", "text": "Ötszög", "isCorrect": false}], "timeLimit": 15}]'::jsonb,
        true,
