        '[{"id": "81322c56-851e-42cb-a5aa-47a35e4b32f6", "text": "1. Hány fokos a derékszög?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "694caeee-b1b1-46f9-8dd2-07a5ccd984ec", "text": "2. Hány csúcsa van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "97fd81ec-8463-443e-acf4-f5cb19442664", "text": "3. Hány éle van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "556728bb-30bf-4543-8976-930c6cd681ab", "text": "4. Milyen egyenesek nem metszik egymást a síkban?", "type": "multiple-choice", "options": [{"id": "2e95f53e-b400-4879-8fff-60d7b57a7012", "text": "Párhuzamos egyenesek", "isCorrect": true}, {"id": "03b15376-ee89-401d-ae6f-b80e7ce1fea7", "text": "Merőleges egyenesek", "isCorrect": false}, {"id": "34f42649-81a8-4f2c-8edd-dafc9fdc5c79", "text": "Metsző egyenesek", "isCorrect": false}, {"id": "ed2c03e2-3787-46d9-8a3b-a57bbadf7c6b", "text": "Félegyenesek", "isCorrect": false}], "timeLimit": 15}, {"id": "357e879d-7277-4a9d-b9de-1648a0f7b4c0", "text": "5. Mennyi egy 6 cm oldalú négyzet kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "662e2c01-d7e3-4282-b463-d81c020740a6", "text": "6. A háromszög belső szögeinek összege 180°.", "type": "true-false", "options": [{"id": "c1dee50a-19fb-43dd-b554-0934e617e724", "text": "Igaz", "isCorrect": true}, {"id": "3fb9d727-1c29-4566-99db-2dd4dfd22ee8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2afaddd2-5a84-452f-83c2-94f89599d7cb", "text": "7. Hány átlója van egy négyszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "eebf8829-445c-4958-a8b0-ed94ad2c8cdf", "text": "8. Milyen szög a 135 fokos szög?", "type": "multiple-choice", "options": [{"id": "cdc4a3c5-837d-478f-a2d3-b7aca485f370", "text": "Tompaszög", "isCorrect": true}, {"id": "eae38300-10f6-4408-803a-914bd10a9807", "text": "Hegyesszög", "isCorrect": false}, {"id": "41bc850f-d4ea-4156-8cea-17bb2b717ab1", "text": "Derékszög", "isCorrect": false}, {"id": "366ba646-d2c8-4378-b67c-86ceb5528366", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "a893d81a-07ac-4612-bdab-0a292ea06eda", "text": "9. A szakasz mindkét irányban véges, két végpontja van.", "type": "true-false", "options": [{"id": "ffdfa682-f4e6-4983-9196-c4e96f24fe27", "text": "Igaz", "isCorrect": true}, {"id": "b2a9dc72-9e00-45d9-b44c-7c507c9a0500", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b09fa468-b331-449d-95b2-547d731acbc0", "text": "10. Minden négyzet egyben téglalap is.", "type": "true-false", "options": [{"id": "46ca1c14-dd31-4cb3-8690-529fe3b161ec", "text": "Igaz", "isCorrect": true}, {"id": "b2533f23-a761-4a91-8bc8-2acec9acc6b8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb,
        true,
