    );

INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at, created_at, updated_at)
    VALUES (
        'b3954209-dd97-4f75-ba39-160154a21d16',
        '21feff02-016d-46e2-bb9d-c27495133b1b',
        '75. óra: Témazáró dolgozat értékelése',
        'A Geometria témazáró dolgozat feladatainak megbeszélése, értékelés.',
        'Matematika',
        '5. osztály',
        'Geometria',
        '[{"id": "7d6a89b6-8e23-4b9c-b8d7-e0c8123d70a9", "text": "Mi a legfontosabb különbség a síkidomok és a testek között?", "type": "multiple-choice", "options": [{"id": "fa8f2089-3c2c-44cf-b265-0c2b3b2f85c8", "text": "A síkidomok kétdimenziósak, a testek háromdimenziósak", "isCorrect": true}, {"id": "e6bdcc18-ddc9-4c67-ad3a-eb3511faaed0", "text": "A síkidomoknak vannak éleik", "isCorrect": false}, {"id": "96e423f0-3843-4c36-85f4-08d885a50ad9", "text": "A testeknek nincs térfogatuk", "isCorrect": false}, {"id": "08ae89df-a5f3-403e-9be3-a6699c6e5a33", "text": "Nincs különbség", "isCorrect": false}], "timeLimit": 15}, {"id": "70820ee5-253d-4cb9-bc9a-54df86a09736", "text": "Hogyan szerkesztünk merőlegest vonalzóval?", "type": "multiple-choice", "options": [{"id": "6b9a71ab-0483-473f-8c58-1525d269d212", "text": "Derékszögű vonalzó segítségével", "isCorrect": true}, {"id": "f8f74d1e-9055-4a7e-8179-2f637b8e0d29", "text": "Sima vonalzóval szemmértékre", "isCorrect": false}, {"id": "1a4833cf-59c9-46c9-a8cb-b738845c2782", "text": "Körző nélkül nem lehet", "isCorrect": false}, {"id": "7dc844e2-1ebb-4169-bd37-ce5ddebc96e1", "text": "Radírral", "isCorrect": false}], "timeLimit": 15}, {"id": "0f6d42e9-baa1-4419-9f55-47247dc19c07", "text": "A témazáróban elkövetett hibák javítása segít a fogalmak pontos megértésében.", "type": "true-false", "options": [{"id": "a9418ebe-5cbd-439f-b19b-9cff8f82417d", "text": "Igaz", "isCorrect": true}, {"id": "bde342b0-0f00-48f3-9441-562fbad66ba7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "162c7958-cb13-4802-8fde-be13f9c6b838", "text": "Hány fokos a teljes kör elforgatása?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "eadb1181-6b37-4d5b-a3f4-adeda972fbf4", "text": "A hegyesszög mindig kisebb, mint a derékszög.", "type": "true-false", "options": [{"id": "389c8e18-6153-45c1-bbf4-782c90453561", "text": "Igaz", "isCorrect": true}, {"id": "8648dca2-987c-42a0-a8df-ef3a9a4553f8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2a1fc8a6-0124-4d20-a7fd-23aebaf29d08", "text": "Mennyi a téglalap kerületképlete (ha oldalai ''a'' és ''b'')?", "type": "multiple-choice", "options": [{"id": "109a92a8-6926-4db1-88aa-bf77c3df3fc7", "text": "K = 2 * (a + b)", "isCorrect": true}, {"id": "e8d51c9b-c7ee-4283-89b3-c90f02d0ed1c", "text": "K = a * b", "isCorrect": false}, {"id": "4ec5c9d1-75b9-4b3e-8a2b-21f116c7e5d3", "text": "K = 4 * a * b", "isCorrect": false}, {"id": "c23036c3-83e9-43ae-87e5-d61422f057e2", "text": "K = a + b", "isCorrect": false}], "timeLimit": 15}, {"id": "a78fbd3a-2ee1-4e92-82fb-41cd4152d667", "text": "Mennyi a négyzet területképlete (ha oldala ''a'')?", "type": "multiple-choice", "options": [{"id": "732f3b4b-507f-422e-a992-89b9cecfaf54", "text": "T = a * a", "isCorrect": true}, {"id": "19cb1b20-d7b1-48d9-8c59-05c3c17b2b60", "text": "T = 4 * a", "isCorrect": false}, {"id": "ad9efcbf-38e6-4229-bf9a-08f8789e2125", "text": "T = 2 * a", "isCorrect": false}, {"id": "77ec1fef-7c2b-45e4-b82d-a00307886ca7", "text": "T = a + a", "isCorrect": false}], "timeLimit": 15}]'::jsonb,
        true,
        NOW(),
        NOW(),
        NOW()
    );